S = [('Inhalt', [('Teil 1: *Vorlesung 1* – erst *Einheiten*, dann die *geradlinige Bewegung*.', 'Willkommen zu Teil eins. Wir gehen Vorlesung eins Folie für Folie durch. Zuerst geht es um Einheiten, danach um die geradlinige Bewegung.'), ('Vier Fragen: Maßeinheiten · Definition · *Vorsatzsilben* · *signifikante Stellen*', 'Der erste Block beantwortet vier Fragen: Was sind Maßeinheiten, wie sind sie definiert, was sind Vorsatzsilben, und was sind signifikante Stellen.')]), ('Wie lang ist eine Elle?', [('Früher: jede Stadt ihre *eigene Elle*.', 'Früher hatte fast jede Stadt ihre eigene Elle. Diese Tabelle zeigt, wie viele Meter eine Elle jeweils war.'), ('Freiburg *0,54 m* · Bayern *0,833 m*', 'In Freiburg war sie null Komma fünf vier Meter lang, in Bayern null Komma acht drei drei Meter.'), ('Die bayerische Elle war *über 50 %* länger.', 'Die bayerische Elle war also über fünfzig Prozent länger. Wer Stoff nach Ellen kaufte, musste genau wissen, welche Elle gemeint ist.')]), ('Was ist eine Maßeinheit?', [('Maßeinheit = vereinbarte *Vergleichsgröße*', 'Deshalb die Definition: Eine Maßeinheit ist eine international vereinbarte Vergleichsgröße.'), ('mit *festem, jederzeit reproduzierbarem* Betrag', 'Entscheidend ist der zweite Teil: Sie hat einen festen Betrag, den man jederzeit und überall reproduzieren kann. Genau das konnte die Elle nicht.'), ('Heute weltweit: das *SI*, eingeführt *1960*', 'Heute gilt weltweit das Internationale Einheitensystem, abgekürzt S I. Es wurde neunzehnhundertsechzig eingeführt.')]), ('Absturz wegen falscher Einheit', [('1999: Marssonde *Mars Climate Orbiter* verglüht', 'Wie teuer ein Einheitenfehler sein kann, zeigt die Marssonde Mars Climate Orbiter. Sie verglühte neunzehnhundertneunundneunzig in der Marsatmosphäre.'), ('Daten in *Pounds of Force* statt in *Newton*', 'Der Hersteller lieferte Kräfte in der amerikanischen Einheit Pound-Force. Das Labor hat sie aber als Newton eingegeben.'), ('1 lbf ≈ *4,45 N* → Kräfte um Faktor 4,45 falsch', 'Ein Pound-Force sind etwa vier Komma vier fünf Newton. Alle Kräfte waren also um diesen Faktor falsch. Die Lehre: Schreib immer die Einheit dazu.')]), ('Das SI', [('Seit *2019*: alle SI-Einheiten über *sieben Konstanten* definiert', 'Seit zweitausendneunzehn sind alle S I Einheiten über sieben feste Naturkonstanten definiert. Kein Metallstab und kein Gewichtsstück mehr.'), ('1) *eindeutig* – jede Größe hat genau eine Einheit', 'Das S I hat vier Eigenschaften. Erstens: Es ist eindeutig. Jede physikalische Größe hat genau eine Einheit.'), ('2) *dezimal* – Vorsätze sind Zehnerpotenzen', 'Zweitens: Es ist dezimal. Kleinere und größere Einheiten entstehen durch Vorsätze, und die sind immer Zehnerpotenzen.'), ('3) *effiziente Nomenklatur* · 4) *kohärent*', 'Drittens hat jede Größe höchstens einen eigenen Einheitennamen. Und viertens ist es kohärent: Man kann ohne zusätzliche Zahlenfaktoren umrechnen. Das schauen wir gleich an einem Beispiel an.')]), ('Die sieben definierenden Konstanten', [('Jede Basisgröße hängt an einer *Naturkonstante*', 'In dieser Tabelle steht für jede Basisgröße die Naturkonstante, an der sie hängt.'), ('Sekunde: *9 192 631 770* Schwingungen der Cäsium-Strahlung', 'Die Sekunde ist die Zeit, in der die Strahlung eines Cäsium-Atoms genau neun Milliarden einhundertzweiundneunzig Millionen sechshunderteinunddreißigtausend siebenhundertsiebzig Mal schwingt.'), ('Meter: Licht legt in 1/299 792 458 s *1 m* zurück', 'Der Meter hängt an der Lichtgeschwindigkeit: Er ist die Strecke, die Licht im Vakuum in einem zweihundertneunundneunzig-millionstel Teil einer Sekunde zurücklegt.'), ('Seit 2019 auch kg, A, K, mol über *h, e, k_B, N_A*', 'Seit zweitausendneunzehn hängen auch Kilogramm, Ampere, Kelvin und Mol an Konstanten: am Planckschen Wirkungsquantum, an der Elementarladung, an der Boltzmann-Konstante und an der Avogadro-Konstante.')]), ('Basisgrößen und Basiseinheiten', [('Sieben *Basisgrößen* mit Symbol und Einheit', 'Die sieben Basisgrößen mit ihrem Formelzeichen und ihrer Einheit.'), ('Achtung: *m* ist Masse – und *m* ist Meter!', 'Achtung, eine typische Verwechslung: m steht als Formelzeichen für die Masse, aber m ist auch die Einheit Meter. Und die Länge hat das Formelzeichen kleines l.'), ('Formelzeichen *kursiv* (Variable), Einheit *aufrecht*', 'Darum schreibt man Formelzeichen kursiv und Einheiten aufrecht. So erkennt man auch im Text sofort, was gemeint ist.')]), ('Ergänzende Informationen', [('Kelvin: Nullpunkt = *absoluter Nullpunkt*', 'Diese Folie ergänzt die Tabelle. Beim Kelvin liegt der Nullpunkt dort, wo keine Molekülbewegung mehr vorliegt, beim absoluten Nullpunkt.'), ('Hier steht 1 K = −273,15 °C – richtig ist *0 K = −273,15 °C*', 'Hier hat sich ein Fehler eingeschlichen: Dort steht ein Kelvin gleich minus zweihundertdreiundsiebzig Komma eins fünf Grad Celsius. Richtig ist: null Kelvin sind minus zweihundertdreiundsiebzig Komma eins fünf Grad Celsius.'), ('Ein *Temperaturunterschied* von 1 K ist gleich groß wie 1 °C.', 'Ein Temperaturunterschied von einem Kelvin ist dagegen genauso groß wie ein Grad Celsius. Deshalb rechnet man bei Differenzen oft einfach mit Kelvin.')]), ('Vorsätze für große Zahlen', [('Vorsatz = *Zehnerpotenz* vor der Einheit', 'Jetzt die Vorsätze. Jeder Vorsatz steht für eine Zehnerpotenz.'), ('Kilo = 10³ · Mega = 10⁶ · Giga = 10⁹', 'Die wichtigsten großen: Kilo ist zehn hoch drei, Mega zehn hoch sechs, Giga zehn hoch neun.'), ('Im Bauwesen: *5 kN* = 5 · 10³ N = 5000 N', 'Im Bauwesen begegnet dir ständig das Kilonewton: Fünf Kilonewton sind fünf mal zehn hoch drei, also fünftausend Newton.')]), ('Vorsätze für kleine Zahlen', [('Milli = 10⁻³ · Mikro = 10⁻⁶ · Nano = 10⁻⁹', 'Nach unten genauso: Milli ist zehn hoch minus drei, Mikro zehn hoch minus sechs, Nano zehn hoch minus neun.'), ('Groß-/Kleinschreibung zählt: *m* = Milli, *M* = Mega', 'Achte auf Groß und Klein: kleines m ist Milli, großes M ist Mega. Das ist ein Faktor von einer Milliarde.')]), ('Das SI ist kohärent', [('Kohärent: Umrechnen *ohne extra Zahlenfaktoren*', 'Kohärent heißt: Die Einheiten passen ohne zusätzliche Zahlenfaktoren zusammen.'), ('F = m · g: 0,1 kg · 9,81 m/s² = *0,981 N*', 'Beispiel eins: Kraft ist Masse mal Beschleunigung. Hundert Gramm Schokolade, also null Komma eins Kilogramm, mal neun Komma acht eins Meter pro Quadratsekunde, ergibt null Komma neun acht eins Newton. Ein Newton ist eben genau ein Kilogramm mal Meter pro Quadratsekunde.'), ('1 N/mm² = 10⁶ N/m² = *1 MPa*', 'Beispiel zwei ist für dich als Bauingenieur wichtig: Ein Newton pro Quadratmillimeter ist genau ein Megapascal.')]), ('Signifikante Stellen', [('Signifikante Stellen = Ziffern, die zur *Genauigkeit* beitragen', 'Signifikante Stellen sind die Ziffern einer Zahl, die etwas über die Genauigkeit aussagen.'), ('Nicht-Null-Ziffern zählen · *eingeschlossene* Nullen zählen', 'Es gibt vier Regeln. Ziffern ungleich null zählen immer: hundertdreiundzwanzig hat drei. Nullen zwischen zwei Ziffern zählen auch: tausendzwei hat vier.'), ('*Führende* Nullen zählen nicht · *Endnullen* nach dem Komma zählen', 'Führende Nullen zählen nicht: null Komma null null eins zwei drei hat nur drei. Endnullen nach dem Komma zählen dagegen: zwei Komma fünf null hat drei, denn die Null sagt, dass genau gemessen wurde.')]), ('Beispiele zu signifikanten Stellen', [('Addition: so viele *Nachkommastellen* wie der ungenaueste Wert', 'Beispiel eins ist eine Addition. Die Breite ist nur auf eine Nachkommastelle bekannt. Also darf auch der Umfang nur eine Nachkommastelle haben: tausenddreiundneunzig Komma acht Meter.'), ('Bsp. 2: oben *6,817*, in der Rechnung *6,871* – Tippfehler', 'Bei Beispiel zwei steht oben eine Masse von sechs Komma acht eins sieben Kilogramm, in der Rechnung aber sechs Komma acht sieben eins. Das ist ein Tippfehler. Richtig gerechnet: sechs Komma acht eins sieben durch achtzehn Komma drei neun ergibt null Komma drei sieben null sieben.'), ('Mal und geteilt: so viele *signifikante Stellen* wie der ungenaueste Faktor', 'Außerdem gilt beim Multiplizieren und Teilen eine andere Regel als beim Addieren: Es zählt die Anzahl der signifikanten Stellen. Beide Werte haben vier, also hat auch das Ergebnis vier: null Komma drei sieben null sieben.'), ('Plausibel? 0,37 kg/cm³ wäre *schwerer als Blei* – gemeint ist wohl dm³', 'Und noch ein Plausibilitätscheck: Null Komma drei sieben Kilogramm pro Kubikzentimeter wäre viel schwerer als Blei. Gemeint ist wohl ein Volumen in Kubikdezimetern.')]), ('Regeln zur Notation', [('Variablen *kursiv*, Konstanten *aufrecht*', 'Jetzt die Mechanik. Zuerst zwei Regeln, die in jeder Übung und Klausur zählen. Erstens: Variablen schreibt man kursiv, Konstanten aufrecht.'), ('x-Achse = *Abszisse* · y-Achse = *Ordinate*', 'Zweitens: Jedes Diagramm braucht beschriftete Achsen. Die waagerechte x-Achse heißt Abszisse, die senkrechte y-Achse heißt Ordinate.'), ('Achsen ohne Beschriftung → *keine Punkte*', 'Und das ist kein Detail: Für Diagramme ohne Achsenbeschriftung gibt es in Übung und Klausur keine Punkte. Also immer Größe und Einheit an jede Achse.')]), ('Skalare und Vektoren', [('Skalar: *eine Zahl* genügt (Länge, Masse, Zeit)', 'Skalare sind Größen, für die eine einzige Zahl genügt. Zum Beispiel Länge, Masse und Zeit.'), ('Vektor: Betrag *und Richtung* (z. B. Verschiebung)', 'Vektoren brauchen zusätzlich eine Richtung. Beispiel Verschiebung: Fünf Meter allein reichen nicht, man muss sagen, wohin.'), ('Schreibweise: *fett* oder mit *Pfeil* über dem Buchstaben', 'Vektoren schreibt man fett oder mit einem Pfeil über dem Buchstaben. Auf Papier nimmst du den Pfeil.')]), ('Bezugssystem, Ortsvektor, Bahnkurve', [('*Bezugssystem* = Koordinatensystem', 'Um eine Bewegung zu beschreiben, braucht man ein Koordinatensystem. In der Physik heißt das Bezugssystem.'), ('*Ortsvektor r(t)* – wo ist der Massepunkt zur Zeit t?', 'Der Ortsvektor r zeigt vom Ursprung zum Massepunkt. Weil sich der Punkt bewegt, ist r eine Funktion der Zeit.'), ('*Bahnkurve* = alle Orte nacheinander', 'Alle Orte, die der Punkt nacheinander durchläuft, bilden die Bahnkurve.'), ('Mittlere Geschwindigkeit: *v_m = Δr / Δt*', 'Die Position allein sagt noch nicht, wie schnell sich der Punkt bewegt. Dafür gibt es die mittlere Geschwindigkeit: Verschiebung geteilt durch Zeitintervall.')]), ('Der Massepunkt', [('Modell *Massepunkt*: alle Teile bewegen sich gleich', 'Wir rechnen mit Massepunkten. Das passt, wenn sich alle Teile eines Körpers gleich bewegen, wie bei der rutschenden Kugel: Alle Pfeile sind gleich lang.'), ('Rollende Kugel: außen *schneller* als innen → kein Massepunkt', 'Bei der rollenden Kugel ist das anders: Oben bewegt sie sich schneller als in der Mitte, am Boden steht sie kurz still. Dann reicht das Modell Massepunkt nicht.')]), ('Ort und Verschiebung', [('Zur Zeit t₁ ist der Punkt bei *x₁ = +3 m*', 'Jetzt die geradlinige Bewegung entlang der x-Achse. Zur Zeit t eins ist der Massepunkt bei x eins gleich plus drei Meter.'), ('Später, zur Zeit t₂: *x₂ = −3 m*', 'Zur späteren Zeit t zwei ist er bei x zwei gleich minus drei Meter.'), ('Δx = x₂ − x₁ = −3 − 3 = *−6 m*', 'Die Verschiebung ist immer Endort minus Anfangsort: minus drei minus drei, also minus sechs Meter.'), ('Zeitintervall *Δt = t₂ − t₁*', 'Genauso ist das Zeitintervall definiert: später minus früher.')]), ('Vorzeichen der Verschiebung', [('Minus = nach *links* (kleinere x) · Plus = nach *rechts*', 'Das Vorzeichen der Verschiebung verrät die Richtung. Minus heißt: Bewegung zu kleineren x-Werten, also nach links. Plus heißt: nach rechts.'), ('Verschiebung = *Betrag* + *Richtung* → Vektor', 'Die Verschiebung hat also einen Betrag, hier sechs Meter, und eine Richtung, hier nach links. Damit ist sie ein Vektor.')]), ('Die Orts-Zeit-Kurve', [('Orts-Zeit-Diagramm: *Zeit t* waagerecht, *Ort x* senkrecht', 'Trägt man den Ort über der Zeit auf, entsteht die Orts-Zeit-Kurve. Waagerecht steht die Zeit in Sekunden, senkrecht der Ort in Metern.'), ('Der Punkt läuft vor, *zurück* und wieder vor.', 'Folge dem Punkt: Bis zwei Sekunden läuft er nach vorne auf zwanzig Meter. Dann geht er zurück bis sechzehn Meter. Ab vier Sekunden läuft er wieder vor, bis sechsunddreißig Meter.'), ('Δx = *16 m* (0 → 1 s) · *−4 m* (2 → 4 s) · *16 m* (5 → 6 s)', 'Die roten Werte sind Verschiebungen: in der ersten Sekunde sechzehn Meter, von zwei bis vier Sekunden minus vier Meter, also zurück, und in der letzten Sekunde wieder sechzehn Meter.')]), ('Durchschnittsgeschwindigkeit', [('v_m = Δx / Δt – Steigung der *Sekante*', 'Die Durchschnittsgeschwindigkeit ist Verschiebung durch Zeit. Im Diagramm ist das die Steigung der Geraden durch zwei Kurvenpunkte, der Sekante.'), ('1 → 2 s: (20 − 16) m / 1 s = *4 m/s*', 'Von einer bis zwei Sekunden: Der Ort geht von sechzehn auf zwanzig Meter. Vier Meter in einer Sekunde, also vier Meter pro Sekunde.'), ('2 → 4 s: (16 − 20) m / 2 s = *−2 m/s*', 'Von zwei bis vier Sekunden: von zwanzig auf sechzehn Meter, also minus vier Meter in zwei Sekunden. Das sind minus zwei Meter pro Sekunde. Minus heißt: Er läuft zurück.')]), ('Von der Sekante zur Tangente', [('Intervall immer kleiner → Sekante wird zur *Tangente*', 'Jetzt machen wir das Zeitintervall immer kleiner. Schau, wie sich die Sekante durch den Punkt bei einer Sekunde dreht.'), ('Steigung: 6 → … → *9 m/s* = Geschwindigkeit genau bei t = 1 s', 'Die Steigung geht von sechs über acht immer näher an neun Meter pro Sekunde. Das ist die Geschwindigkeit genau im Moment t gleich eine Sekunde.'), ('Tangentensteigung = *1. Ableitung* x′(t)', 'Mathematisch ist die Steigung der Tangente die erste Ableitung der Orts-Zeit-Funktion nach der Zeit.')]), ('Die Geschwindigkeit', [('Durchschnitt: *v_m = Δx/Δt = (x₂ − x₁)/(t₂ − t₁)*', 'Hier die beiden Definitionen. Die Durchschnittsgeschwindigkeit ist Δx durch Δt, also Ortsdifferenz durch Zeitdifferenz.'), ('Momentan: *v = lim Δx/Δt = dx/dt = ẋ*', 'Die momentane Geschwindigkeit ist der Grenzwert für Δt gegen null. Das ist die Ableitung dx nach dt. Physiker schreiben dafür auch x Punkt: Der Punkt bedeutet immer Ableitung nach der Zeit.'), ('Einheit: *m/s*', 'Die Einheit ist in beiden Fällen Meter pro Sekunde.')]), ('Geschwindigkeits-Zeit-Kurve', [('v(t) aus der Steigung der x-t-Kurve', 'Trägt man die Geschwindigkeit über der Zeit auf, erhält man die Geschwindigkeits-Zeit-Kurve. Sie gehört zur selben Bewegung wie eben.'), ('v = 0 bei *2 s* und *4 s* – genau da kehrt der Punkt um', 'Bei zwei und bei vier Sekunden ist die Geschwindigkeit null. Genau dort hatte die Orts-Zeit-Kurve ihren Hochpunkt und ihren Tiefpunkt: Der Punkt kehrt um.'), ('v < 0 zwischen 2 s und 4 s: er läuft *zurück*', 'Dazwischen ist die Geschwindigkeit negativ, der Punkt läuft zurück. Am kleinsten ist sie bei drei Sekunden: minus drei Meter pro Sekunde.')]), ('Die Beschleunigung', [('Beschleunigung = *Änderungsrate der Geschwindigkeit*', 'Die Beschleunigung beschreibt, wie schnell sich die Geschwindigkeit ändert. Wieder ist es die Steigung einer Sekante, jetzt in der v-t-Kurve.'), ('1 → 2 s: v fällt von *9* auf *0 m/s*', 'Zwischen einer und zwei Sekunden fällt die Geschwindigkeit von neun auf null Meter pro Sekunde.'), ('a_m = Δv/Δt = (0 − 9) m/s / 1 s = *−9 m/s²*', 'Also minus neun Meter pro Sekunde in einer Sekunde. Die mittlere Beschleunigung ist minus neun Meter pro Quadratsekunde.')]), ('Definition der Beschleunigung', [('Durchschnitt: *a_m = Δv/Δt* · Einheit *m/s²*', 'Die Definitionen sind genauso gebaut wie bei der Geschwindigkeit. Die mittlere Beschleunigung ist Δv durch Δt, die Einheit ist Meter pro Quadratsekunde.'), ('Momentan: *a = dv/dt = v̇ = ẍ* – zweite Ableitung von x', 'Die momentane Beschleunigung ist die Ableitung der Geschwindigkeit, also v Punkt. Weil v schon die Ableitung von x ist, ist a die zweite Ableitung: x zwei Punkt.')]), ('Wann wird eine Bewegung langsamer?', [('Rot: v(t) · Blau: *a(t)* – eine Gerade', 'Hier stehen Geschwindigkeit und Beschleunigung im selben Diagramm. Rot die Geschwindigkeit, blau die Beschleunigung. Sie steigt gleichmäßig von minus achtzehn auf plus achtzehn.'), ('*Verzögert*, wenn v und a *verschiedene Vorzeichen* haben', 'Die Regel: Die Bewegung wird langsamer, wenn Geschwindigkeit und Beschleunigung verschiedene Vorzeichen haben. Das sind die blauen Bereiche.'), ('0–2 s: v > 0, a < 0 → langsamer · 3–4 s: v < 0, a > 0 → langsamer', 'Von null bis zwei Sekunden ist v positiv und a negativ, er bremst. Von drei bis vier ist v negativ und a positiv, er bremst wieder.'), ('2–3 s: *beide negativ* → er wird *schneller* (rückwärts)', 'Zwischen zwei und drei Sekunden sind beide negativ. Obwohl a negativ ist, wird er dort schneller, nämlich rückwärts. Negative Beschleunigung heißt also nicht automatisch bremsen.')]), ('x, v und a im Überblick', [('Steigung von x(t) → *v(t)*', 'Zusammengefasst: Die Steigung der Orts-Zeit-Kurve ist die Geschwindigkeit.'), ('Steigung von v(t) → *a(t)*', 'Und die Steigung der Geschwindigkeits-Zeit-Kurve ist die Beschleunigung. Wo x waagerecht verläuft, ist v null. Wo v am tiefsten ist, ist a null.')]), ('Rechenbeispiel: v und a bei t = 6 s', [('Gegeben: *x = t³ − 9 t² + 24 t* – genau unsere Kurve', 'Jetzt rechnen wir. Gegeben ist x gleich t hoch drei minus neun t Quadrat plus vierundzwanzig t. Das ist übrigens genau die Kurve aus allen Diagrammen dieser Vorlesung.'), ('v = ẋ = *3 t² − 18 t + 24* (1. Ableitung)', 'Für die Geschwindigkeit leitest du einmal ab. Aus t hoch drei wird drei t Quadrat, aus minus neun t Quadrat wird minus achtzehn t, aus vierundzwanzig t wird vierundzwanzig.'), ('t = 6 s: 3 · 36 − 18 · 6 + 24 = 108 − 108 + 24 = *24 m/s*', 'Bei sechs Sekunden: drei mal sechsunddreißig ist hundertacht, achtzehn mal sechs ist auch hundertacht. Die heben sich weg, übrig bleiben vierundzwanzig Meter pro Sekunde.'), ('a = v̇ = *6 t − 18* → t = 6 s: 36 − 18 = *18 m/s²*', 'Für die Beschleunigung leitest du noch einmal ab: sechs t minus achtzehn. Bei sechs Sekunden sind das sechsunddreißig minus achtzehn, also achtzehn Meter pro Quadratsekunde.')]), ('Blitz und Donner', [('Schall: *c_S ≈ 343 m/s* · Licht: praktisch sofort', 'Zum Schluss eine Anwendung: Wie weit ist ein Gewitter weg? Schall ist mit etwa dreihundertdreiundvierzig Metern pro Sekunde unterwegs, Licht ist praktisch sofort da.'), ('1 km braucht 1000 m / 343 m/s ≈ *3 s*', 'Für einen Kilometer braucht der Schall also tausend durch dreihundertdreiundvierzig, etwa drei Sekunden.'), ('Regel: *Sekunden ÷ 3 = Kilometer*', 'Daher die Regel: Zähl die Sekunden zwischen Blitz und Donner und teil sie durch drei. Das ist die Entfernung in Kilometern. Damit ist Vorlesung eins geschafft.')])]
